+		r.Header.Add("Content-Type", "application/x-www-form-urlencoded")
+		StdJSONHandler(jh, t.Logf).ServeHTTP(w, r)
+		data := checkSuccess(t, w)
+		if data["num"] != "42" {
+			t.Errorf(`data["num"]=%v (%T), want 42`, data["num"], data["num"])
