+	private2      = mustCIDR("172.16.0.0/12")
+	private3      = mustCIDR("192.168.0.0/16")
+	cgNAT         = mustCIDR("100.64.0.0/10")
+	linkLocalIPv4 = mustCIDR("169.254.0.0/16")
