+func (sb *StatusBuilder) AddUser(id tailcfg.UserID, up tailcfg.UserProfile) {
+	sb.mu.Lock()
+	defer sb.mu.Unlock()
+	if sb.locked {
+		log.Printf("[unexpected] ipnstate: AddUser after Locked")
+		return
+	}
+
+	if sb.st.User == nil {
+		sb.st.User = make(map[tailcfg.UserID]tailcfg.UserProfile)
+	}
