+	}
+
+	sb.mu.Lock()
+	defer sb.mu.Unlock()
+	if sb.locked {
+		log.Printf("[unexpected] ipnstate: AddPeer after Locked")
+		return
+	}
+
+	if sb.st.Peer == nil {
+		sb.st.Peer = make(map[key.Public]*PeerStatus)
+	}
